        session,
        runOptions))
    {
        if (update.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(update.Text))
        {
            Console.Write(update.Text);
        }
    }

    Console.WriteLine();
    Console.WriteLine(new string('─', 40));
    Console.WriteLine();
    notebook.Clear();
}

Console.WriteLine("Goodbye!");

