using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string ModelId = "gpt-4o-mini-2024-07-18";

// --- Tools ---
var notebook = new Notebook();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
        {
            // Replace this stub with a real search API (Bing, Google, Brave, etc.)
            Console.WriteLine($"  🔍  Searching: \"{query}\"");
            return Task.FromResult<IReadOnlyList<SearchResult>>(
            [
                new($"https://example.com/1?q={Uri.EscapeDataString(query)}",
                    $"Overview of {query}",
                    $"{query} is a broad topic covering key concepts, history, and recent developments. "
                  + "Experts note significant progress in the field over the past decade."),
                new($"https://example.com/2?q={Uri.EscapeDataString(query)}",
                    $"Recent advances in {query}",
                    $"A 2025 survey highlights breakthroughs in {query}, including improved methodologies "
                  + "and wider adoption across industries."),
                new($"https://example.com/3?q={Uri.EscapeDataString(query)}",
                    $"Practical applications of {query}",
                    $"Real-world applications of {query} span healthcare, finance, and education. "
                  + "Case studies show measurable impact on efficiency and outcomes."),
            ]);
        },
        "web_search",
        "Search the web for information on a topic. Returns titles, URLs, and snippets."),

    AIFunctionFactory.Create(
        ([Description("A concise title for the note")] string title,
         [Description("The content to save")] string content) =>
        {
            notebook.Add(title, content);
            Console.WriteLine($"  📝  Note saved: \"{title}\"");
            return $"Note \"{title}\" saved successfully.";
        },
        "save_note",
        "Save a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () =>
        {
            var notes = notebook.GetAll();
            Console.WriteLine($"  📖  Reading {notes.Count} note(s)");
            return notes.Count == 0
                ? "No notes saved yet."
                : JsonSerializer.Serialize(notes, JsonContext.Default.IReadOnlyListNote);
        },
        "read_notes",
        "Read all previously saved research notes."),
};

// --- Chat client ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(ModelId)
    .AsIChatClient();

// --- Agent ---
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions =
        """
        You are a research agent. When given a topic:
        1. Use web_search to find information (run multiple searches with different queries).
        2. Use save_note to record key findings from each search.
        3. Use read_notes to review everything you have collected.
        4. Produce a final summary with sections: Overview, Key Findings, and Sources.
        Be thorough — search at least twice with varied queries before summarizing.
        """,
};

var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [.. tools],
    },
};

// --- Run ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔬  Research Agent  🔬        ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Type a topic to research, or       ║");
Console.WriteLine("║  'quit' to exit.                    ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Topic> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.WriteLine($"Researching: {topic}");
    Console.WriteLine(new string('─', 40));

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine();
    Console.WriteLine(new string('─', 40));
    Console.WriteLine();
    notebook.Clear();
}

Console.WriteLine("Goodbye!");

// --- Supporting types ---

record SearchResult(string Url, string Title, string Snippet);

record Note(string Title, string Content);

class Notebook
{
    private readonly List<Note> _notes = [];

    public void Add(string title, string content) => _notes.Add(new Note(title, content));
    public IReadOnlyList<Note> GetAll() => _notes.AsReadOnly();
    public void Clear() => _notes.Clear();
}

[System.Text.Json.Serialization.JsonSerializable(typeof(IReadOnlyList<Note>))]
partial class JsonContext : System.Text.Json.Serialization.JsonSerializerContext;

